# Helper: safely sum matrix columns (works for both sparse and dense matrices)
def safe_sum(X):
    return X.sum(axis=0).A1 if issparse(X) else np.asarray(X.sum(axis=0)).flatten()

# Helper: compute percent expressed for a set of features (transcripts or genes)
def pct_expressed(adata_sub, features):
    mat = (adata_sub[:, features].X > 0)
    return np.array(mat.sum(axis=0)).flatten() / adata_sub.n_obs * 100

# Compute cell-level psi for a set of transcripts (vectorized)
def compute_cell_level_psi(adata_sub, transcripts, epsilon=1e-6):
    M = adata_sub[:, transcripts].X
    if issparse(M):
        M = M.toarray()
    gene_counts = M.sum(axis=1)
    with np.errstate(divide='ignore', invalid='ignore'):
        psi = np.divide(M, gene_counts[:, None] + epsilon)
    return psi

# Build isoform metrics table without any filtering
def build_isoform_metrics_table(
    adata: ad.AnnData,
    group_column: str,
    condition_column: str = None,  # optional nesting argument
    comparisons: list = None,
    epsilon: float = 1e-6,
    n_jobs: int = -1
) -> pd.DataFrame:
    # Work on a copy so as not to modify the original AnnData object
    adata_copy = adata.copy()

    def process_comparison(group1_idx, group2_idx, transcripts, group1_label, group2_label):
        rows = []
        adata_g1 = adata_copy[group1_idx]
        adata_g2 = adata_copy[group2_idx]

        # Compute counts, mean expression, and percent expression for all transcripts
        counts_g1 = safe_sum(adata_g1.X)
        counts_g2 = safe_sum(adata_g2.X)
        mean_expr_g1 = counts_g1 / adata_g1.n_obs
        mean_expr_g2 = counts_g2 / adata_g2.n_obs
        pct_expr_g1 = pct_expressed(adata_g1, transcripts)
        pct_expr_g2 = pct_expressed(adata_g2, transcripts)

        # Get transcript metadata from all transcripts
        var_df = adata_copy.var.loc[transcripts].copy()
        var_df['transcript_id'] = var_df.index

        # Process each gene in a vectorized manner
        for gene, gene_df in var_df.groupby('geneId'):
            transcripts_in_gene = gene_df['transcript_id'].tolist()
            # Compute cell-level psi matrices for the gene's transcripts in each group
            psi_matrix_g1 = compute_cell_level_psi(adata_g1, transcripts_in_gene, epsilon)
            psi_matrix_g2 = compute_cell_level_psi(adata_g2, transcripts_in_gene, epsilon)
            avg_psi_g1 = psi_matrix_g1.mean(axis=0)
            avg_psi_g2 = psi_matrix_g2.mean(axis=0)

            # Compute vectorized metrics
            log_fc = np.log((avg_psi_g1 + epsilon) / (avg_psi_g2 + epsilon))
            delta_psi = avg_psi_g1 - avg_psi_g2

            # Identify indices of these transcripts within the overall transcripts array
            idx = np.nonzero(np.in1d(transcripts, transcripts_in_gene))[0]

            gene_records = pd.DataFrame({
                'comparison': [f"{group1_label}__{group2_label}"] * len(transcripts_in_gene),
                'gene_id': gene,
                'transcript_id': transcripts_in_gene,
                'group_1': group1_label,
                'group_2': group2_label,
                'count_group1': counts_g1[idx],
                'count_group2': counts_g2[idx],
                'mean_expr_group1': mean_expr_g1[idx],
                'mean_expr_group2': mean_expr_g2[idx],
                'percent_expr_group1': pct_expr_g1[idx],
                'percent_expr_group2': pct_expr_g2[idx],
                'avg_psi_group1': avg_psi_g1,
                'log_fc': log_fc,
                'delta_psi': delta_psi,
                'n_cells_group1': adata_g1.n_obs,
                'n_cells_group2': adata_g2.n_obs,
                'total_cells': adata_g1.n_obs + adata_g2.n_obs,
                'total_count': counts_g1[idx] + counts_g2[idx]
            })
            rows.append(gene_records)
        return pd.concat(rows, ignore_index=True) if rows else pd.DataFrame()

    tasks = []
    if condition_column:
        primary_groups = sorted(adata.obs[group_column].unique())
        conditions = sorted(adata.obs[condition_column].unique())
        for pg in primary_groups:
            pg_idx = adata.obs[group_column] == pg
            for c1, c2 in itertools.combinations(conditions, 2):
                g1_idx = pg_idx & (adata.obs[condition_column] == c1)
                g2_idx = pg_idx & (adata.obs[condition_column] == c2)
                group1_label = f"{pg}:{c1}"
                group2_label = f"{pg}:{c2}"
                tasks.append((g1_idx, g2_idx, adata_copy.var.index.values, group1_label, group2_label))
    else:
        groups = sorted(adata.obs[group_column].unique())
        comparisons = comparisons or itertools.combinations(groups, 2)
        for g1, g2 in comparisons:
            g1_idx = adata.obs[group_column] == g1
            g2_idx = adata.obs[group_column] == g2
            tasks.append((g1_idx, g2_idx, adata_copy.var.index.values, g1, g2))

    results = Parallel(n_jobs=n_jobs)(
        delayed(process_comparison)(g1_idx, g2_idx, transcripts, g1_lbl, g2_lbl)
        for g1_idx, g2_idx, transcripts, g1_lbl, g2_lbl in tasks
    )
    return pd.concat(results, ignore_index=True) if results else pd.DataFrame()


