def build_gene_metrics_table(
    adata: ad.AnnData,
    group_column: str,
    condition_column: str = None,  # optional nesting argument
    comparisons: list = None,
    epsilon: float = 1e-6,
    n_jobs: int = -1
) -> pd.DataFrame:
    from scipy.sparse import issparse
    from joblib import Parallel, delayed
    import itertools

    # Get gene-level matrix (no filtering applied)
    adata_gene = get_sot_gene_matrix(adata)
    if 'geneId' not in adata_gene.var.columns:
        adata_gene.var['geneId'] = adata_gene.var.index
    adata_filt = adata_gene.copy()

    # Helper: safely sum matrix columns (works for both sparse and dense matrices)
    def safe_sum(X):
        return X.sum(axis=0).A1 if issparse(X) else np.asarray(X.sum(axis=0)).flatten()

    # Helper: compute percent expressed for a set of genes
    def pct_expressed(adata_sub, genes):
        mat = (adata_sub[:, genes].X > 0)
        return np.array(mat.sum(axis=0)).flatten() / adata_sub.n_obs * 100

    if condition_column:
        # Nested comparisons: for each primary group, compare every pair of conditions.
        primary_groups = sorted(adata_filt.obs[group_column].unique())
        conditions = sorted(adata_filt.obs[condition_column].unique())
        if comparisons is None:
            comparisons = [
                (g, c1, c2) for g in primary_groups for c1, c2 in itertools.combinations(conditions, 2)
            ]

        def process_nested_comparison(group, cond1, cond2):
            # Subset the cells for each condition within the same primary group.
            obs_g1 = adata_filt.obs[
                (adata_filt.obs[group_column] == group) & (adata_filt.obs[condition_column] == cond1)
            ].index
            obs_g2 = adata_filt.obs[
                (adata_filt.obs[group_column] == group) & (adata_filt.obs[condition_column] == cond2)
            ].index
            adata_g1 = adata_filt[obs_g1]
            adata_g2 = adata_filt[obs_g2]

            counts_g1 = safe_sum(adata_g1.X)
            counts_g2 = safe_sum(adata_g2.X)
            n1 = adata_g1.n_obs
            n2 = adata_g2.n_obs
            mean_expr_g1 = counts_g1 / n1
            mean_expr_g2 = counts_g2 / n2
            genes = adata_filt.var.index.values
            pct_expr_g1 = pct_expressed(adata_g1, genes)
            pct_expr_g2 = pct_expressed(adata_g2, genes)
            log_fc = np.log((mean_expr_g1 + epsilon) / (mean_expr_g2 + epsilon))
            total_count = counts_g1 + counts_g2

            return pd.DataFrame({
                'comparison': f"{group}:{cond1}__{group}:{cond2}",
                'gene_id': genes,
                'group': group,
                'condition_1': cond1,
                'condition_2': cond2,
                'count_group1': counts_g1,
                'count_group2': counts_g2,
                'mean_expr_group1': mean_expr_g1,
                'mean_expr_group2': mean_expr_g2,
                'percent_expr_group1': pct_expr_g1,
                'percent_expr_group2': pct_expr_g2,
                'log_fc': log_fc,
                'n_cells_group1': n1,
                'n_cells_group2': n2,
                'total_cells': n1 + n2,
                'total_count': total_count
            })

        results = Parallel(n_jobs=n_jobs)(
            delayed(process_nested_comparison)(group, cond1, cond2)
            for group, cond1, cond2 in comparisons
        )
    else:
        # Non-nested comparisons.
        groups = sorted(adata_filt.obs[group_column].unique())
        if comparisons is None:
            comparisons = list(itertools.combinations(groups, 2))

        def process_comparison(group1, group2):
            adata_g1 = adata_filt[adata_filt.obs[group_column] == group1]
            adata_g2 = adata_filt[adata_filt.obs[group_column] == group2]

            counts_g1 = safe_sum(adata_g1.X)
            counts_g2 = safe_sum(adata_g2.X)
            n1 = adata_g1.n_obs
            n2 = adata_g2.n_obs
            mean_expr_g1 = counts_g1 / n1
            mean_expr_g2 = counts_g2 / n2
            genes = adata_filt.var.index.values
            pct_expr_g1 = pct_expressed(adata_g1, genes)
            pct_expr_g2 = pct_expressed(adata_g2, genes)
            log_fc = np.log((mean_expr_g1 + epsilon) / (mean_expr_g2 + epsilon))
            total_count = counts_g1 + counts_g2

            return pd.DataFrame({
                'comparison': f"{group1}__{group2}",
                'gene_id': genes,
                'group_1': group1,
                'group_2': group2,
                'count_group1': counts_g1,
                'count_group2': counts_g2,
                'mean_expr_group1': mean_expr_g1,
                'mean_expr_group2': mean_expr_g2,
                'percent_expr_group1': pct_expr_g1,
                'percent_expr_group2': pct_expr_g2,
                'log_fc': log_fc,
                'n_cells_group1': n1,
                'n_cells_group2': n2,
                'total_cells': n1 + n2,
                'total_count': total_count
            })

        results = Parallel(n_jobs=n_jobs)(
            delayed(process_comparison)(g1, g2) for g1, g2 in comparisons
        )

    return pd.concat(results, ignore_index=True) if results else pd.DataFrame()


# %% ../nbs/005_switch_search.ipynb 6
class SwitchSearch(ad.AnnData):
    def __init__(self, anndata_obj: ad.AnnData, n_jobs=-1, compute_metrics=True, group_column='cell_type', condition_column=None):
        # Work on a copy so that the original object is not modified.
        super().__init__(anndata_obj.copy())
        self.n_jobs = n_jobs
        if 'transcriptId' not in self.var.columns:
            self.var['transcriptId'] = self.var.index
        if compute_metrics:
            try:
                self.transcript_metrics = build_isoform_metrics_table(
                    self,
                    group_column=group_column,  # or your preferred grouping column
                    comparisons=None,
                    epsilon=1e-6,
                    n_jobs=self.n_jobs
                )
            except Exception as e:
                warnings.warn(f"Failed to build transcript metrics table: {e}")
                self.transcript_metrics = None

            try:
                from allos.preprocessing import get_sot_gene_matrix
                adata_gene = get_sot_gene_matrix(self)
                if 'geneId' not in adata_gene.var.columns:
                    adata_gene.var['geneId'] = adata_gene.var.index
                self.gene_metrics_table = build_gene_metrics_table(
                    adata_gene,
                    group_column=group_column,
                    comparisons=None,
                    epsilon=1e-6,
                    n_jobs=self.n_jobs
                )
            except Exception as e:
                warnings.warn(f"Failed to build gene metrics table: {e}")
                self.gene_metrics_table = None
        else:
            # Do not compute new metrics; they can be assigned later.
            self.transcript_metrics = None
            self.gene_metrics_table = None

    def compare_gene_chi2(self, group1_label, group2_label, gene_id, cell_group_column='cell_type', epsilon=1e-6):
        # Extract group1 data for the gene.
        group1 = self[self.obs[cell_group_column] == group1_label]
        mask1 = (group1.var['geneId'] == gene_id)
        if mask1.sum() == 0:
            return None
        isoform_ids = group1.var.index[mask1]

        # Extract group1 counts for each isoform.
        data1 = group1[:, mask1].X
        counts1 = safe_sum(data1)

        # Extract group2 data for the gene.
        group2 = self[self.obs[cell_group_column] == group2_label]
        mask2 = (group2.var['geneId'] == gene_id)
        if mask2.sum() == 0:
            return None
        isoform_ids_group2 = group2.var.index[mask2]

        # Determine common isoforms between the two groups.
        common_isoforms = np.intersect1d(isoform_ids, isoform_ids_group2)
        if len(common_isoforms) == 0:
            return None

        # Subset group data to these common isoforms.
        mask1_common = group1.var.index.isin(common_isoforms)
        mask2_common = group2.var.index.isin(common_isoforms)
        data1 = group1[:, mask1_common].X
        data2 = group2[:, mask2_common].X
        counts1 = safe_sum(data1)
        counts2 = safe_sum(data2)

        # Align counts by transcript.
        df1 = pd.DataFrame({'transcript': group1.var.index[mask1_common], 'count': counts1}).set_index('transcript')
        df2 = pd.DataFrame({'transcript': group2.var.index[mask2_common], 'count': counts2}).set_index('transcript')
        try:
            counts1_ordered = df1.loc[common_isoforms, 'count'].values
            counts2_ordered = df2.loc[common_isoforms, 'count'].values
        except Exception:
            return None

        # Build the contingency table: rows = isoforms, columns = [group1, group2].
        contingency = np.vstack([counts1_ordered, counts2_ordered]).T

        # Perform chi-square test.
        chi2_stat, p_value, dof, expected = chi2_contingency(contingency)

        result = {
            "gene_id": gene_id,
            "group_1": group1_label,
            "group_2": group2_label,
            "chi2_stat": chi2_stat,
            "p_value": p_value,
            "dof": dof
        }
        return result

    def _filter_genes(self, group1_label, group2_label, cell_group_column='cell_type',
                      min_count=9, min_log_fold_change=0.5, filter_loud=False, n_jobs_override=None):
        """
        Filters the AnnData and creates a new SwitchSearch instance
        without recalculating the metrics tables. The fixed metrics tables are passed along.
        """
        # Cache indices for each group in the full AnnData
        group1_idx = self.obs[cell_group_column] == group1_label
        group2_idx = self.obs[cell_group_column] == group2_label

        # Compute global gene counts and filter out genes with low overall counts.
        gene_counts_total = safe_sum(self.X)
        valid_mask = gene_counts_total > min_count
        adata_slice = self[:, valid_mask].copy()

        # Update group indices for the slice.
        group1_idx_slice = adata_slice.obs[cell_group_column] == group1_label
        group2_idx_slice = adata_slice.obs[cell_group_column] == group2_label

        # Filter further by nonzero counts in each group.
        nz1 = np.asarray((adata_slice[group1_idx_slice].X != 0).sum(axis=0)).flatten()
        nz2 = np.asarray((adata_slice[group2_idx_slice].X != 0).sum(axis=0)).flatten()
        valid_nz = (nz1 > min_count) & (nz2 > min_count)
        adata_slice = adata_slice[:, valid_nz].copy()

        # Group transcripts by gene using the metadata.
        df_var = adata_slice.var.copy()
        groups = df_var.groupby('geneId').groups  # dict: gene_id -> index labels of transcripts

        # Convert data for both groups once.
        data_group1 = adata_slice[group1_idx_slice].X
        data_group2 = adata_slice[group2_idx_slice].X
        if issparse(data_group1):
            data_group1 = data_group1.toarray()
        if issparse(data_group2):
            data_group2 = data_group2.toarray()

        # Determine genes to remove based on isoform switching.
        to_remove = []
        for gene_id, col_labels in groups.items():
            int_inds = adata_slice.var.index.get_indexer(col_labels)
            X1 = data_group1[:, int_inds]
            X2 = data_group2[:, int_inds]
            total1 = X1.sum()
            total2 = X2.sum()
            if total1 == 0 or total2 == 0:
                to_remove.append(gene_id)
                continue
            prop1 = X1.sum(axis=0) / (total1 + 1e-6)
            prop2 = X2.sum(axis=0) / (total2 + 1e-6)
            lfc = np.abs(np.log((prop1 + 1e-6) / (prop2 + 1e-6)))
            if not np.any(lfc >= min_log_fold_change):
                to_remove.append(gene_id)

        final_mask = ~adata_slice.var['geneId'].isin(to_remove)
        filtered_data = adata_slice[:, final_mask].copy()
        effective_n_jobs = n_jobs_override if n_jobs_override is not None else self.n_jobs

        new_obj = SwitchSearch(filtered_data, n_jobs=effective_n_jobs, compute_metrics=False)
        new_obj.gene_metrics_table = self.gene_metrics_table
        new_obj.transcript_metrics = self.transcript_metrics

        return new_obj

    def find_switching_isoforms_chi2(self,
                                     cell_group_column='cell_type',
                                     min_count=30,
                                     min_log_fold_change=0.5,
                                     filter_loud=False,
                                     min_fdr=0.05,
                                     return_transcript_metrics=False,
                                     n_jobs=None):
        """
        Runs the chi-square test for differential isoform usage across cell groups defined by cell_group_column.
        Note: Nested comparisons (using a condition column) are not supported in this version.
        """
        if n_jobs is None:
            n_jobs = self.n_jobs

        results = []
        cell_counts = self.obs[cell_group_column].value_counts()
        valid_cell_types = cell_counts[cell_counts >= min_count].index.tolist()
        comparisons = list(itertools.combinations(valid_cell_types, 2))
        
        def process_comparison(g1, g2):
            filtered_ss = self._filter_genes(
                g1, g2,
                cell_group_column=cell_group_column,
                min_count=min_count,
                min_log_fold_change=min_log_fold_change,
                filter_loud=filter_loud
            )
            gene_ids = np.unique(filtered_ss.var['geneId'])
            res_comparison = []
            for gene in gene_ids:
                res = filtered_ss.compare_gene_chi2(g1, g2, gene, cell_group_column=cell_group_column)
                if res is not None:
                    res_comparison.append(res)
            return res_comparison
        
        if n_jobs == 1:
            for g1, g2 in comparisons:
                results.extend(process_comparison(g1, g2))
        else:
            parallel_results = Parallel(n_jobs=n_jobs)(
                delayed(process_comparison)(g1, g2) for g1, g2 in comparisons
            )
            for res in parallel_results:
                if res:
                    results.extend(res)
                        
        results_df = pd.DataFrame(results)
        if not results_df.empty and 'p_value' in results_df.columns:
            results_df['adj_pval'] = multipletests(results_df['p_value'], method='fdr_bh')[1]
            results_df = results_df[results_df['adj_pval'] <= min_fdr]

        if return_transcript_metrics and self.transcript_metrics is not None:
            filtered_transcript_metrics = self.transcript_metrics[
                (self.transcript_metrics['gene_id'].isin(results_df['gene_id'])) &
                ((self.transcript_metrics['percent_expr_group1'] >= 0.2) |
                 (self.transcript_metrics['percent_expr_group2'] >= 0.2)) &
                (self.transcript_metrics['total_count'] >= 30) &
                (self.transcript_metrics['delta_psi'].abs() >= 0.1)
            ].copy()

            transcript_metrics_swapped = filtered_transcript_metrics.rename(
                columns={"group_1": "group_2", "group_2": "group_1"}
            )
            augmented_results = pd.merge(
                results_df, 
                filtered_transcript_metrics, 
                on=["gene_id", "group_1", "group_2"], 
                how="left"
            )
            augmented_results_swapped = pd.merge(
                results_df, 
                transcript_metrics_swapped, 
                on=["gene_id", "group_1", "group_2"], 
                how="left"
            )
            augmented_results = augmented_results.fillna(augmented_results_swapped)
            augmented_results = augmented_results.dropna()
        elif self.gene_metrics_table is not None:
            gene_metrics_swapped = self.gene_metrics_table.rename(
                columns={"group_1": "group_2", "group_2": "group_1"}
            )
            augmented_results = pd.merge(
                results_df, 
                self.gene_metrics_table, 
                on=["gene_id", "group_1", "group_2"], 
                how="left"
            )
            augmented_results_swapped = pd.merge(
                results_df, 
                gene_metrics_swapped, 
                on=["gene_id", "group_1", "group_2"], 
                how="left"
            )
            augmented_results = augmented_results.fillna(augmented_results_swapped)
            augmented_results = augmented_results.dropna()
        else:
            augmented_results = results_df

        return augmented_results


# %% ../nbs/005_switch_search.ipynb 7
def filter_sample_replicated_transcripts(adata, sample_col='sample', min_samples=2, min_umi=1):
    """
    Filters out transcripts that are not detected above a minimum UMI threshold 
    in at least a specified number of samples (replicates).

    Parameters:
      adata: AnnData object containing transcript-level counts.
      sample_col: Column in adata.obs that identifies the replicate/sample.
      min_samples: Minimum number of samples in which the transcript must be expressed.
      min_umi: Minimum UMI count in a sample for the transcript to be considered "expressed".
    
    Returns:
      A new AnnData object containing only transcripts that replicate across samples.
    """
    # Get unique sample identifiers.
    samples = adata.obs[sample_col].unique()
    
    # Dictionary to count in how many samples each transcript is expressed.
    transcript_presence = {tx: 0 for tx in adata.var_names}
    
    # Loop through each sample, calculate transcript counts, and mark transcripts that pass the threshold.
    for sample in samples:
        sample_adata = adata[adata.obs[sample_col] == sample]
        # Use your safe_sum helper to support both sparse and dense matrices.
        counts = safe_sum(sample_adata.X)
        # Loop over transcripts: if count > min_umi, mark as present.
        for tx, count in zip(adata.var_names, counts):
            if count > min_umi:
                transcript_presence[tx] += 1
    
    # Select transcripts that are expressed in at least min_samples samples.
    transcripts_to_keep = [tx for tx, count in transcript_presence.items() if count >= min_samples]
    print(f"Filtering out {adata.n_vars - len(transcripts_to_keep)} transcripts that are sample-specific")
    
    # Return a new AnnData object with only the replicated transcripts.
    return adata[:, transcripts_to_keep].copy()





# %% ../nbs/005_switch_search.ipynb 13
def get_top_n_isoforms(adata, gene_id, top_n=5, strip=False):
    """
    Get the top_n transcript IDs for a given gene based on overall average expression.

    Parameters:
    - adata: AnnData object containing transcript-level data.
    - gene_id: The gene ID to search for corresponding isoforms.
    - top_n: The number of top isoforms to return based on overall average expression.
    - strip: Boolean indicating whether to strip the dot and everything after from the ID.

    Returns:
    - A list of top_n transcript IDs.
    """
    # Identify isoforms for the given gene ID
    isoforms = adata.var[adata.var['geneId'] == gene_id].index
    if len(isoforms) == 0:
        print(f"No isoforms found for gene ID: {gene_id}")
        return []

    # Calculate the overall average expression for each isoform
    overall_expr = adata.to_df()[isoforms].mean()

    # Get the top_n isoforms by average expression
    top_isoforms = overall_expr.sort_values(ascending=False).head(top_n).index.tolist()

    # Strip the dot and everything after from the ID if strip is True
    if strip:
        top_isoforms = [isoform.split('.')[0] for isoform in top_isoforms]

    return top_isoforms
